1	package edgefleet
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strconv"
12		"strings"
13	)
14	
15	// AggregateResult is one closed window output line.
16	type AggregateResult struct {
17		Key   string `json:"key"`
18		Start int64  `json:"start"`
19		End   int64  `json:"end"`
20		Count int64  `json:"count"`
21		Sum   int64  `json:"sum"`
22	}
23	
24	// InputError reports a fatal problem with one physical input line.
25	type InputError struct {
26		Line   int
27		Reason string
28	}
29	
30	func (e *InputError) Error() string {
31		return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
32	}
33	
34	type windowID struct {
35		start int64 // inclusive window start in milliseconds since time zero
36		key   string
37	}
38	
39	type windowState struct {
40		end   int64 // exclusive window end in milliseconds
41		count int64
42		sum   int64
43	}
44	
45	// RunAggregate reads line-delimited JSON records from r and writes closed
46	// window results, one JSON object per line, to out. windowMillis must be a
47	// positive signed 64-bit integer. Windows are fixed-length, start at time
48	// zero and use a left-closed right-open interval. Closure is driven solely by
49	// input watermarks: a window whose end is less than or equal to the current
50	// watermark is emitted once, ordered by end ascending and then by key in
51	// UTF-8 byte order. Late events (event time below the current watermark) are
52	// reported on lateLog with their physical line number and skipped. Fatal
53	// record problems return *InputError; results already written to out stay
54	// written, and open windows are not flushed at end of input.
55	//
56	// This is the legacy single-watermark mode: records carry no partition field
57	// and any extra fields are ignored. Use RunAggregatePartitioned to merge
58	// several independent input sources of the same stream.
59	func RunAggregate(r io.Reader, windowMillis int64, out io.Writer, lateLog io.Writer) error {
60		return RunAggregatePartitioned(r, windowMillis, 0, out, lateLog)
61	}
62	
63	// RunAggregatePartitioned reads line-delimited JSON records from r and writes
64	// closed window results, one JSON object per line, to out. windowMillis must
65	// be a positive signed 64-bit integer. partitions selects the input mode:
66	//
67	//   - partitions == 0: legacy single-watermark mode. Records do not carry a
68	//     partition field; any extra fields are ignored.
69	//   - partitions > 0: partitioned mode, merging partitions independent input
70	//     sources of the same stream. Every event and watermark record must carry
71	//     an integer "partition" in [0,partitions). Each partition advances its
72	//     own watermark; no effective watermark exists until every partition has
73	//     reported at least once, afterwards the effective watermark is the
74	//     minimum of the per-partition values. Window closure and late-event
75	//     checks use this minimum, so one partition's larger watermark can never
76	//     close a window or drop an event ahead of the others. A partition
77	//     watermark may repeat or jump forward but never move backwards.
78	//
79	// partitions < 0 is an error. Windows, ordering, late-event reporting,
80	// overflow checks and end-of-input behavior are otherwise identical to
81	// RunAggregate.
82	func RunAggregatePartitioned(r io.Reader, windowMillis, partitions int64, out io.Writer, lateLog io.Writer) error {
83		if windowMillis <= 0 {
84			return fmt.Errorf("window length must be a positive signed 64-bit integer, got %d", windowMillis)
85		}
86		if partitions < 0 {
87			return fmt.Errorf("partition count must be a positive signed 64-bit integer, got %d", partitions)
88		}
89		s := &aggregateState{
90			windowMillis:  windowMillis,
91			windows:       make(map[windowID]*windowState),
92			out:           out,
93			lateLog:       lateLog,
94			partitions:    partitions,
95			partWatermark: make(map[int64]*int64),
96		}
97	
98		scanner := bufio.NewScanner(r)
99		scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024*1024)
100		lineNo := 0
101		for scanner.Scan() {
102			lineNo++
103			line := strings.TrimSuffix(scanner.Text(), "\r")
104			if strings.TrimSpace(line) == "" {
105				continue
106			}
107			if err := s.processLine(line, lineNo); err != nil {
108				return err
109			}
110		}
111		return scanner.Err()
112	}
113	
114	type aggregateState struct {
115		windowMillis int64
116		windows      map[windowID]*windowState
117		out          io.Writer
118		lateLog      io.Writer
119	
120		partitions    int64 // 0 = legacy single-watermark mode
121		watermark     *int64
122		partWatermark map[int64]*int64 // partition -> last watermark; partitioned mode only
123	}
124	
125	func (s *aggregateState) processLine(line string, lineNo int) error {
126		var obj map[string]json.RawMessage
127		if err := json.Unmarshal([]byte(line), &obj); err != nil {
128			return &InputError{Line: lineNo, Reason: "invalid JSON record: " + err.Error()}
129		}
130	
131		typeRaw, ok := obj["type"]
132		if !ok {
133			return &InputError{Line: lineNo, Reason: `missing required string field "type"`}
134		}
135		recordType, err := decodeString(typeRaw, "type")
136		if err != nil {
137			return &InputError{Line: lineNo, Reason: err.Error()}
138		}
139	
140		switch recordType {
141		case "event":
142			return s.processEvent(obj, lineNo)
143		case "watermark":
144			return s.processWatermark(obj, lineNo)
145		default:
146			return &InputError{Line: lineNo, Reason: fmt.Sprintf("unknown record type %q", recordType)}
147		}
148	}
149	
150	func (s *aggregateState) processEvent(obj map[string]json.RawMessage, lineNo int) error {
151		key, err := requiredString(obj, "key", lineNo)
152		if err != nil {
153			return err
154		}
155		if key == "" {
156			return &InputError{Line: lineNo, Reason: `field "key" must be a non-empty string`}
157		}
158		eventTime, err := requiredNonNegInt64(obj, "time", lineNo)
159		if err != nil {
160			return err
161		}
162		value, err := requiredInt64(obj, "value", lineNo)
163		if err != nil {
164			return err
165		}
166		if _, err := s.requiredPartition(obj, lineNo); err != nil {
167			return err
168		}
169	
170		if s.watermark != nil && eventTime < *s.watermark {
171			fmt.Fprintf(s.lateLog, "line %d: late event time=%d below current watermark %d, skipped\n", lineNo, eventTime, *s.watermark)
172			return nil
173		}
174	
175		start := eventTime - eventTime%s.windowMillis
176		if start > math.MaxInt64-s.windowMillis {
177			return &InputError{Line: lineNo, Reason: fmt.Sprintf("window end overflow for key %q window starting at %d with length %d", key, start, s.windowMillis)}
178		}
179		end := start + s.windowMillis
180	
181		id := windowID{start: start, key: key}
182		st := s.windows[id]
183		if st == nil {
184			st = &windowState{end: end}
185			s.windows[id] = st
186		}
187		if st.count == math.MaxInt64 {
188			return &InputError{Line: lineNo, Reason: fmt.Sprintf("event count overflow for key %q window [%d,%d)", key, start, end)}
189		}
190		if value > 0 && st.sum > math.MaxInt64-value {
191			return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
192		}
193		if value < 0 && st.sum < math.MinInt64-value {
194			return &InputError{Line: lineNo, Reason: fmt.Sprintf("cumulative sum overflow for key %q window [%d,%d): %d + %d", key, start, end, st.sum, value)}
195		}
196		st.count++
197		st.sum += value
198		return nil
199	}
200	
201	func (s *aggregateState) processWatermark(obj map[string]json.RawMessage, lineNo int) error {
202		next, err := requiredNonNegInt64(obj, "time", lineNo)
203		if err != nil {
204			return err
205		}
206		p, err := s.requiredPartition(obj, lineNo)
207		if err != nil {
208			return err
209		}
210	
211		if s.partitions == 0 {
212			if s.watermark != nil && next < *s.watermark {
213				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark moved backwards from %d to %d", *s.watermark, next)}
214			}
215			s.watermark = &next
216		} else {
217			if prev, ok := s.partWatermark[p]; ok && next < *prev {
218				return &InputError{Line: lineNo, Reason: fmt.Sprintf("watermark for partition %d moved backwards from %d to %d", p, *prev, next)}
219			}
220			s.partWatermark[p] = &next
221			s.watermark = s.effectiveWatermark()
222		}
223	
224		if s.watermark == nil {
225			return nil
226		}
227		return s.closeWindows(*s.watermark)
228	}
229	
230	// effectiveWatermark returns the minimum of the per-partition watermarks once
231	// every partition has reported at least one, or nil otherwise.
232	func (s *aggregateState) effectiveWatermark() *int64 {
233		if len(s.partWatermark) != int(s.partitions) {
234			return nil
235		}
236		var min int64
237		first := true
238		for _, w := range s.partWatermark {
239			if first || *w < min {
240				min = *w
241				first = false
242			}
243		}
244		return &min
245	}
246	
247	// requiredPartition returns the record's partition index. In legacy mode it
248	// returns 0 without inspecting the record, so extra fields stay ignored.
249	func (s *aggregateState) requiredPartition(obj map[string]json.RawMessage, lineNo int) (int64, error) {
250		if s.partitions == 0 {
251			return 0, nil
252		}
253		p, err := requiredInt64(obj, "partition", lineNo)
254		if err != nil {
255			return 0, err
256		}
257		if p < 0 || p >= s.partitions {
258			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be an integer in range [0,%d), got %d", "partition", s.partitions, p)}
259		}
260		return p, nil
261	}
262	
263	func (s *aggregateState) closeWindows(watermark int64) error {
264		type pending struct {
265			id windowID
266			st *windowState
267		}
268		var ready []pending
269		for id, st := range s.windows {
270			if st.end <= watermark {
271				ready = append(ready, pending{id: id, st: st})
272			}
273		}
274		sort.Slice(ready, func(i, j int) bool {
275			if ready[i].st.end != ready[j].st.end {
276				return ready[i].st.end < ready[j].st.end
277			}
278			return ready[i].id.key < ready[j].id.key
279		})
280		for _, p := range ready {
281			encoded, err := json.Marshal(AggregateResult{
282				Key:   p.id.key,
283				Start: p.id.start,
284				End:   p.st.end,
285				Count: p.st.count,
286				Sum:   p.st.sum,
287			})
288			if err != nil {
289				return err
290			}
291			if _, err := s.out.Write(append(encoded, '\n')); err != nil {
292				return err
293			}
294			delete(s.windows, p.id)
295		}
296		return nil
297	}
298	
299	func requiredString(obj map[string]json.RawMessage, field string, lineNo int) (string, error) {
300		raw, ok := obj[field]
301		if !ok {
302			return "", &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required string field %q", field)}
303		}
304		value, err := decodeString(raw, field)
305		if err != nil {
306			return "", &InputError{Line: lineNo, Reason: err.Error()}
307		}
308		return value, nil
309	}
310	
311	func requiredInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
312		raw, ok := obj[field]
313		if !ok {
314			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("missing required integer field %q", field)}
315		}
316		value, err := decodeInt64(raw, field)
317		if err != nil {
318			return 0, &InputError{Line: lineNo, Reason: err.Error()}
319		}
320		return value, nil
321	}
322	
323	func requiredNonNegInt64(obj map[string]json.RawMessage, field string, lineNo int) (int64, error) {
324		value, err := requiredInt64(obj, field, lineNo)
325		if err != nil {
326			return 0, err
327		}
328		if value < 0 {
329			return 0, &InputError{Line: lineNo, Reason: fmt.Sprintf("field %q must be a non-negative integer, got %d", field, value)}
330		}
331		return value, nil
332	}
333	
334	func decodeString(raw json.RawMessage, field string) (string, error) {
335		trimmed := bytes.TrimSpace(raw)
336		if len(trimmed) == 0 || trimmed[0] != '"' {
337			return "", fmt.Errorf("field %q must be a JSON string, got %s", field, string(trimmed))
338		}
339		var value string
340		if err := json.Unmarshal(trimmed, &value); err != nil {
341			return "", fmt.Errorf("field %q must be a JSON string: %v", field, err)
342		}
343		return value, nil
344	}
345	
346	func decodeInt64(raw json.RawMessage, field string) (int64, error) {
347		trimmed := bytes.TrimSpace(raw)
348		if len(trimmed) == 0 {
349			return 0, fmt.Errorf("field %q must be a signed 64-bit integer", field)
350		}
351		switch trimmed[0] {
352		case '"', '{', '[', 't', 'f', 'n':
353			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
354		}
355		value, err := strconv.ParseInt(string(trimmed), 10, 64)
356		if err != nil {
357			if numErr, ok := err.(*strconv.NumError); ok && numErr.Err == strconv.ErrRange {
358				return 0, fmt.Errorf("field %q integer out of signed 64-bit range: %s", field, string(trimmed))
359			}
360			return 0, fmt.Errorf("field %q must be a signed 64-bit integer, got %s", field, string(trimmed))
361		}
362		return value, nil
363	}
364

