	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

func TestAggregateClosureOrderByEndThenUTF8Key(t *testing.T) {
	input := strings.Join([]string{
