		t.Fatalf("earlier output retained, got %q want %q", stdout, want)
	}
}

// Resume validation: the resume time must be at least the partition's own
// previous watermark and the current effective watermark; equality resumes.
func TestAggregateIdleResumeBoundaries(t *testing.T) {
	cases := []struct {
		name      string
		resume    string
		wantError bool
		wantInMsg string
	}{
		{"below own previous", `{"type":"watermark","time":999,"partition":1}`, true, "previous watermark"},
		{"equal to both", `{"type":"watermark","time":2000,"partition":1}`, false, ""},
		{"above both", `{"type":"watermark","time":3000,"partition":1}`, false, ""},
		{"below effective", `{"type":"watermark","time":1500,"partition":1}`, true, "effective watermark"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			base := strings.Join([]string{
				`{"type":"event","key":"k","time":100,"value":1,"partition":0}`,
				`{"type":"watermark","time":2000,"partition":0}`,
				`{"type":"watermark","time":2000,"partition":1}`, // p1 own previous = 2000
				`{"type":"watermark","time":5000,"partition":0}`, // effective stays 2000 (p1)
				`{"type":"idle","partition":1}`,                 // exclude p1; effective jumps to 5000
				``,
			}, "\n")
			input := base + tc.resume + "\n"
			_, _, err := runPartitioned(t, input, 1000, 2)
			if tc.wantError && err == nil {
				t.Fatal("expected error, got nil")
			}
			if !tc.wantError && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if tc.wantError {
				inputErr, ok := err.(*InputError)
				if !ok {
					t.Fatalf("expected *InputError, got %T: %v", err, err)
				}
				if inputErr.Line != 6 {
					t.Errorf("line = %d, want 6", inputErr.Line)
				}
				if !strings.Contains(inputErr.Reason, tc.wantInMsg) {
					t.Errorf("reason = %q, want substring %q", inputErr.Reason, tc.wantInMsg)
				}
			}
		})
	}
}

