// All idle before any effective watermark was ever produced: it stays
// unknown, so no window closes and no event is late.
func TestAggregateAllIdleNeverProducedStaysUnknown(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"idle","partition":0}`,
		`{"type":"idle","partition":1}`,
		`{"type":"watermark","time":5000,"partition":0}`, // resume alone: p1 still idle
		`{"type":"event","key":"k","time":1,"value":1,"partition":0}`, // accepted: no effective wm
	}, "\n")
	stdout, stderr, err := runPartitioned(t, input, 1000, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stdout != "" {
		t.Fatalf("idleness is not an infinite watermark, got %q", stdout)
	}
	if stderr != "" {
		t.Fatalf("no late judgment with no effective watermark, got %q", stderr)
	}
}

