// All idle before any effective watermark was ever produced: it stays
// unknown. When a partition later resumes alone, the effective watermark
// becomes its value (min over the remaining active set) — idleness was not
// an infinite watermark.
func TestAggregateAllIdleNeverProducedStaysUnknown(t *testing.T) {
	beforeResume := strings.Join([]string{
		`{"type":"idle","partition":0}`,
		`{"type":"idle","partition":1}`, // all idle, none ever reported: unknown
	}, "\n")
	_, _, err := runPartitioned(t, beforeResume+"\n", 1000, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	// Sanity-check the unknown state directly: with no effective watermark
	// an event is accepted rather than judged late.
	input := strings.Join([]string{
		`{"type":"idle","partition":0}`,
		`{"type":"idle","partition":1}`,
		`{"type":"watermark","time":1000,"partition":0}`, // resume: p1 idle, active set {p0} -> 1000
	}, "\n")
	stdout, _, err := runPartitioned(t, input, 1000, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if stdout != "" {
		t.Fatalf("watermark 1000 closes no window, got %q", stdout)
	}
}

