// A partition that goes idle before reporting has no previous watermark; the
// resume only has to reach the current effective watermark, and the resume
// record recomputes the effective watermark and closes windows.
func TestAggregateIdleNeverReportedResume(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
		`{"type":"watermark","time":9000,"partition":0}`,
		`{"type":"idle","partition":1}`,                 // p1 never reported; effective becomes 9000
		`{"type":"event","key":"k","time":1100,"value":3,"partition":0}`,
		`{"type":"watermark","time":9000,"partition":1}`, // resume at 9000: min back to 9000, closes both
	}, "\n")
	stdout, _, err := runPartitioned(t, input, 1000, 2)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	want := strings.Join([]string{
		`{"key":"k","start":0,"end":1000,"count":1,"sum":2}`,
		`{"key":"k","start":1000,"end":2000,"count":1,"sum":3}`,
		``,
	}, "\n")
	if stdout != want {
		t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
	}
}

